<div class="field"><label for="<?= e($field) ?>"><?= e($label) ?> <span class="required">*</span></label><select id="<?= e($field) ?>" name="<?= e($field) ?>" required <?= isset($errors[$field]) ? 'aria-invalid="true" aria-describedby="error-' . e($field) . '"' : '' ?>><?php foreach ($options as $value): ?><option value="<?= e($value) ?>" <?= $data[$field]===$value ? 'selected' : '' ?>><?= e($value) ?></option><?php endforeach ?></select><?php if (isset($errors[$field])): ?><span class="field-error" id="error-<?= e($field) ?>"><?= e($errors[$field]) ?></span><?php endif ?></div>
